graph = {
    "vendor_a": {"acquired_by": "company_x"},
    "company_x": {"works_with": ["supplier_1", "supplier_2"]},
}

def traverse(graph, start_entity, relationship_chain):
    # walk the graph along a chain of relationships
    current = start_entity
    for relationship in relationship_chain:
        current = graph.get(current, {}).get(relationship)
        if current is None:
            return None
    return current

# follow a two-hop relationship chain
result = traverse(graph, "vendor_a", ["acquired_by", "works_with"])
print("Traversal result:", result)
